edits.after:
.gira-slider-bar input[type="range"]:focus {
  outline: none;
}
/* The WebKit thumb is the only enabled hit target above. Firefox needs its own
   thumb and an enabled range input for both blind and slat dragging. */
@supports selector(input::-moz-range-thumb) {
  .gira-slider-bar input[type="range"] {
    -moz-appearance: none;
    pointer-events: auto;
  }
  .gira-slider-bar input[type="range"]::-moz-range-track {
    background: transparent;
    border: 0;
  }
  .gira-slider-bar input[type="range"]::-moz-range-thumb {
    -moz-appearance: none;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 50%;
    border: 1px solid #c8c8c8;
    background: linear-gradient(to right, #e1e1e1 0%, #fafafa 100%);
    box-shadow: 3px 0 5px 0 rgba(0, 0, 0, 0.2), inset 1px 0 1px #ffffff;
  }
  .gira-slider-bar input[type="range"]::-moz-range-thumb:active {
    background: linear-gradient(to right, #d7d7d7 0%, #e6e6e6 100%);
    box-shadow: 3px 0 5px 0 rgba(0, 0, 0, 0.2), inset 1px 0 1px #e6e6e6;
  }
}
